"""Regenerate both llms-full.txt bundles and the docs copy of the root llms.txt."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main() -> None:
    sources = [
        ROOT / "README.md",
        ROOT / "docs/installation.md",
        ROOT / "docs/quickstart.md",
        ROOT / "docs/input_formats.md",
        *sorted((ROOT / "docs/tutorials").glob("*.md")),
        ROOT / "docs/faq.md",
        ROOT / "docs/agent_guide.md",
        ROOT / "docs/mcp.md",
    ]
    parts = [
        "# STAIG full documentation\n\n"
        "> Generated by `python docs/build_llms_full.py`; do not edit this file.\n\n"
        "The sections below concatenate repository sources verbatim. Relative links are\n"
        "relative to each named source file. Regenerate after changing any source page.\n"
        "README performance claims should be interpreted alongside the benchmark\n"
        "provenance limits in the agent guide; a documentation bundle is not validation.\n"
    ]
    for source in sources:
        relative = source.relative_to(ROOT).as_posix()
        parts.append(f"\n---\n\n<!-- Source: {relative} -->\n\n" + source.read_text(encoding="utf-8"))
    content = "\n".join(parts).rstrip() + "\n"
    for target in (ROOT / "llms-full.txt", ROOT / "docs/llms-full.txt"):
        target.write_text(content, encoding="utf-8")
    (ROOT / "docs/llms.txt").write_bytes((ROOT / "llms.txt").read_bytes())
    print(f"Generated llms-full.txt and docs/llms-full.txt from {len(sources)} sources; copied llms.txt")


if __name__ == "__main__":
    main()
